func (r tableSearchOptimizationDetailsRow) convert() (*TableSearchOptimizationDetails, error) {
	result := &TableSearchOptimizationDetails{
		ExpressionId: r.ExpressionId,
		Method:       r.Method,
		Target:       r.Target,
		Active:       r.Active == "true",
	}
	if v, err := datatypes.ParseDataType(r.TargetDataType); err != nil {
		return nil, fmt.Errorf("parsing datatypes. data type: %w", err)
	} else {
		result.TargetDataType = v
	}
	return result, nil
}

